    const mcd=holdings.find(h=>h.id==='MCD');if(mcd){analyst(mcd,{house:'Morgan Stanley',analyst:'n. v.',date:'2026-09-14',rating:'Equal Weight',target:308,reason:'Equal Weight bestätigt; Kursziel auf 308 USD gesenkt. Der anstehende Investor Day am 23.09. ist der nächste wichtige Strategie-Katalysator.',quality:'Historische Güte: n. v.',source:'https://www.ad-hoc-news.de/boerse/news/corporate-news/mcdonald-s-stock-slips-as-analysts-cut-price-targets/70105639'});trigger(mcd,{date:'2026-09-23',title:'Investor Day',background:'Management soll Strategie und mittelfristige Prioritäten vor dem Hintergrund eines anspruchsvollen Nachfrageumfelds konkretisieren.',direction:'neutral',criteria:[1,1,1],source:'https://www.ad-hoc-news.de/boerse/news/corporate-news/mcdonalds-stock-heads-into-the-open-after-a-2-0-percent-gain/70104103',sourceName:'McDonald’s / Marktberichte',status:'bestätigt'});mcd.next='23.09.2026 · Investor Day';mcd.lastChangedAt=STAMP;mcd.changedSections=['Analysten','Termin/Trigger'];mcd.updateStatus='updated';mcd.updateTag='NEU'}
