  function badge(el,label){if(!el||el.querySelector('.update-badge'))return;const b=document.createElement('span');b.className='update-badge';b.textContent=label;el.prepend(b)}
  function mark(){const chip=document.getElementById('content-state-chip'),text=document.getElementById('content-state');if(chip&&text){text.textContent=`Inhalte: ${fmt(STAMP)}`;chip.classList.remove('status-ok','status-error','status-closed');chip.classList.add('status-partial');chip.title='US-Börsen regulär geöffnet. Acht US-Werte geprüft. Holdings-Datei nicht erreichbar – letzter bestätigter Bestand verwendet. 12er-Bestand gegen Dashboard und Marktdaten-Symbole abgeglichen; keine Position entfernt.'}document.querySelectorAll('.update-badge').forEach(e=>e.remove());document.querySelectorAll('.holding').forEach(c=>{c.classList.remove('content-changed','content-partial');const h=holdings.find(x=>x.id===c.dataset.id);if(CHANGED.has(c.dataset.id)){c.classList.add('content-changed');c.title=`Heute inhaltlich aktualisiert · ${(h?.changedSections||[]).join(', ')}`}else if(h&&CHECKED.has(h.id))c.title=`Letzte Inhaltsprüfung: ${fmt(STAMP)} · Keine inhaltliche Änderung`});if(selected==='CAT')document.querySelectorAll('#tab-events .news-item').forEach(e=>{/Autonomes Hauling/.test(e.textContent||'')&&badge(e.querySelector('.news-top'),'NEU')});if(selected==='MCD'){document.querySelectorAll('#tab-research tbody tr').forEach(e=>{/Morgan Stanley/.test(e.textContent||'')&&badge(e.querySelector('td'),'NEU')});document.querySelectorAll('#tab-events .trigger').forEach(e=>{/Investor Day/.test(e.textContent||'')&&badge(e.querySelector('.item-top'),'NEU')})}if(selected==='AMZN')document.querySelectorAll('#tab-events .news-item').forEach(e=>{/21 Air/.test(e.textContent||'')&&badge(e.querySelector('.news-top'),'NEU')});if(selected==='RNG')document.querySelectorAll('#tab-events .trigger').forEach(e=>{/Piper Sandler Growth Frontiers/.test(e.textContent||'')&&badge(e.querySelector('.item-top'),'NEU')});const footer=document.querySelector('footer.shell');if(footer)footer.textContent='Market Agent · Datenstand 15.09.2026 · 17:00 · Quellen in jedem Eintrag'}
  async function boot(){if(!(await ready()))return;apply();renderCards();renderDetail();mark();[500,1500,4000,8000].forEach(ms=>setTimeout(()=>{try{renderCards();renderDetail();mark()}catch(_){}},ms));document.addEventListener('click',e=>{if(e.target.closest('.holding,.tab,.filter'))setTimeout(mark,0)});window.addEventListener('pageshow',()=>setTimeout(mark,0))}boot();
